WITH latest_match AS (SELECT s.id, s.customer_id, s.device, s.started_at, latest.event_type FROM sessions s JOIN LATERAL (SELECT c.event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, customer_id, COUNT_IF(event_type = 'click') AS click_events, COUNT(*) AS event_count, SIZE(COLLECT_SET(event_type)) AS num_event_types, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', started_at) ORDER BY COUNT(*) DESC) AS event_count_percent_rank FROM latest_match GROUP BY quarter_start, customer_id ORDER BY event_count DESC
